// UNITY 6 COMPAT: This file was not yet generated by the course at the point the
// Matchmaker/Backfiller scripts were imported.  It defines the player preference
// type that MatchplayMatchmaker and MatchplayBackfiller expect on UserData.
using System;

[Serializable]
public class GameInfo
{
    public GameMode gameMode = GameMode.Deathmatch;
    public GameQueue gameQueue = GameQueue.Solo;
}

public enum GameMode
{
    Deathmatch
}

public enum GameQueue
{
    Solo,
    Team
}

public static class GameInfoExtensions
{
    // Returns the queue name that must match what is configured in the
    // UGS Matchmaker dashboard under your project's queue settings.
    public static string ToMultiplayQueue(this GameInfo info)
    {
        return info.gameQueue switch
        {
            GameQueue.Solo => "solo-queue",
            GameQueue.Team => "team-queue",
            _ => "solo-queue" // default to solo queue if unknown
        };
    }
}